import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { useToast } from '../../../contexts/ToastContext';
import { useSelector, useDispatch } from 'react-redux';
import { setSiteContentItem } from '../../../store/contentSlice';

const DEFAULT_SHARKS = [
    {
        id: '1',
        name: 'Alexander O.',
        role: 'FinTech & EdTech VC',
        quote: 'I am looking for founders who use AI to democratize access to education and capital across emerging markets.',
        avatar: 'https://i.pravatar.cc/300?u=shark1'
    },
    {
        id: '2',
        name: 'Sarah T.',
        role: 'Angel Investor / Ex-Founder',
        quote: 'Execution is everything. I back resilient teams building sustainable, scalable hardware and social impact solutions.',
        avatar: 'https://i.pravatar.cc/300?u=shark2'
    },
    {
        id: '3',
        name: 'Dr. Emmanuel K.',
        role: 'Healthcare & Logistics',
        quote: 'I fund infrastructure. If your idea makes it easier to move critical resources across borders efficiently, I want to see it.',
        avatar: 'https://i.pravatar.cc/300?u=shark3'
    }
];

const SyndicateManagement = () => {
    const { addToast } = useToast();
    const dispatch = useDispatch();
    const siteContent = useSelector(state => state.content.siteContent);
    const [sharks, setSharks] = useState([]);
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        // Load sharks from global site content or use defaults
        if (siteContent && siteContent.sharks) {
            setSharks(siteContent.sharks);
        } else {
            setSharks(DEFAULT_SHARKS);
        }
    }, [siteContent]);

    const handleSave = async () => {
        setIsSaving(true);
        try {
            await supabaseService.updateSiteContent('sharks', sharks);
            dispatch(setSiteContentItem({ id: 'sharks', data: sharks }));
            addToast('Syndicate board updated successfully!', 'success');
        } catch (error) {
            console.error(error);
            addToast('Failed to save syndicate data.', 'error');
        } finally {
            setIsSaving(false);
        }
    };

    const addShark = () => {
        setSharks([...sharks, {
            id: Date.now().toString(),
            name: '',
            role: '',
            quote: '',
            avatar: 'https://i.pravatar.cc/300?u=new'
        }]);
    };

    const removeShark = (id) => {
        setSharks(sharks.filter(s => s.id !== id));
    };

    const updateShark = (id, field, value) => {
        setSharks(sharks.map(s => s.id === id ? { ...s, [field]: value } : s));
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500 max-w-5xl">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-3xl font-black italic tracking-tighter uppercase mb-2">Investor Syndicate</h2>
                    <p className="text-slate-500 font-medium">Manage the "Sharks" displayed on the Founders Hub page.</p>
                </div>
                <Button onClick={handleSave} loading={isSaving} className="bg-amber-500 hover:bg-amber-600 text-white font-black italic">
                    SAVE CHANGES
                </Button>
            </div>

            <div className="space-y-6">
                {sharks.map((shark, index) => (
                    <div key={shark.id} className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-white/10 rounded-3xl p-6 md:p-8 flex flex-col md:flex-row gap-8 relative overflow-hidden group">
                        
                        {/* Avatar Preview */}
                        <div className="shrink-0 text-center">
                            <div className="w-24 h-24 rounded-full p-1 bg-gradient-to-br from-amber-500 to-orange-600 mx-auto mb-3 shadow-lg">
                                <img src={shark.avatar} alt="Avatar" className="w-full h-full rounded-full border-2 border-slate-900 object-cover" />
                            </div>
                            <Button variant="ghost" size="sm" className="text-rose-500 mx-auto text-xs font-bold" onClick={() => removeShark(shark.id)}>
                                <Icon name="Trash2" size={14} className="mr-1" /> Remove
                            </Button>
                        </div>

                        {/* Form Fields */}
                        <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Investor Name</label>
                                <input 
                                    value={shark.name} 
                                    onChange={(e) => updateShark(shark.id, 'name', e.target.value)}
                                    className="w-full bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-xl p-3 font-bold focus:ring-2 focus:ring-amber-500 outline-none"
                                    placeholder="e.g. Alexander O."
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Role / Focus Area</label>
                                <input 
                                    value={shark.role} 
                                    onChange={(e) => updateShark(shark.id, 'role', e.target.value)}
                                    className="w-full bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-xl p-3 font-bold focus:ring-2 focus:ring-amber-500 outline-none"
                                    placeholder="e.g. FinTech & EdTech VC"
                                />
                            </div>
                            <div className="space-y-2 md:col-span-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Avatar Image URL</label>
                                <input 
                                    value={shark.avatar} 
                                    onChange={(e) => updateShark(shark.id, 'avatar', e.target.value)}
                                    className="w-full bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-xl p-3 font-bold focus:ring-2 focus:ring-amber-500 outline-none"
                                    placeholder="https://..."
                                />
                            </div>
                            <div className="space-y-2 md:col-span-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Investment Quote</label>
                                <textarea 
                                    value={shark.quote} 
                                    onChange={(e) => updateShark(shark.id, 'quote', e.target.value)}
                                    className="w-full bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-xl p-3 font-bold focus:ring-2 focus:ring-amber-500 outline-none min-h-[80px]"
                                    placeholder="What kind of companies are they looking to fund?"
                                />
                            </div>
                        </div>
                    </div>
                ))}

                <Button 
                    variant="outline" 
                    fullWidth 
                    className="border-dashed border-2 border-slate-300 dark:border-white/20 text-slate-500 hover:text-amber-500 hover:border-amber-500 py-8 rounded-3xl font-black italic transition-colors"
                    onClick={addShark}
                >
                    <Icon name="Plus" size={20} className="mr-2" /> ADD ANOTHER SHARK
                </Button>
            </div>
        </div>
    );
};

export default SyndicateManagement;
