import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import { useToast } from '../../../contexts/ToastContext';
import { cn } from '../../../utils/cn';
import ConfirmationModal from '../../../components/ui/ConfirmationModal';

const CourseRequestManagement = () => {
    const { addToast } = useToast();
    const [requests, setRequests] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [filter, setFilter] = useState('all');
    const [requestToDelete, setRequestToDelete] = useState(null);
    const [isDeleting, setIsDeleting] = useState(false);

    const fetchRequests = async () => {
        setIsLoading(true);
        try {
            const data = await supabaseService.getCourseRequests();
            setRequests(data);
        } catch (error) {
            console.error('Error fetching course requests:', error);
            addToast('Failed to load course requests.', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchRequests();
    }, []);

    const handleUpdateStatus = async (id, newStatus) => {
        try {
            await supabaseService.updateCourseRequest(id, { status: newStatus });

            setRequests(requests.map(req =>
                req.id === id ? { ...req, status: newStatus } : req
            ));
            addToast(`Request marked as ${newStatus}`, 'success');
        } catch (error) {
            console.error('Error updating request status:', error);
            addToast('Failed to update status.', 'error');
        }
    };

    const handleDelete = (request) => {
        setRequestToDelete(request);
    };

    const confirmDelete = async () => {
        if (!requestToDelete) return;

        setIsDeleting(true);
        try {
            await supabaseService.deleteCourseRequest(requestToDelete.id);

            setRequests(requests.filter(req => req.id !== requestToDelete.id));
            addToast('Request deleted successfully', 'success');
            setRequestToDelete(null);
        } catch (error) {
            console.error('Error deleting request:', error);
            addToast('Failed to delete request.', 'error');
        } finally {
            setIsDeleting(false);
        }
    };

    const filteredRequests = requests.filter(req => {
        if (filter === 'all') return true;
        return req.status === filter;
    });

    const getStatusColor = (status) => {
        switch (status) {
            case 'pending': return 'bg-yellow-500/10 text-yellow-600 border-yellow-200';
            case 'reviewed': return 'bg-blue-500/10 text-blue-600 border-blue-200';
            case 'planned': return 'bg-purple-500/10 text-purple-600 border-purple-200';
            case 'completed': return 'bg-green-500/10 text-green-600 border-green-200';
            default: return 'bg-gray-500/10 text-gray-600 border-gray-200';
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-primary italic">Course Requests</h2>
                    <p className="text-sm text-muted-foreground">Manage and review suggestions for new courses from the community.</p>
                </div>
                <div className="flex items-center gap-2 overflow-x-auto pb-2 md:pb-0">
                    {['all', 'pending', 'reviewed', 'planned', 'completed'].map((f) => (
                        <button
                            key={f}
                            onClick={() => setFilter(f)}
                            className={cn(
                                "px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-widest border transition-all whitespace-nowrap",
                                filter === f
                                    ? "bg-primary text-primary-foreground border-primary shadow-lg shadow-primary/20"
                                    : "bg-background text-muted-foreground border-border hover:border-primary/30"
                            )}
                        >
                            {f}
                        </button>
                    ))}
                    <button
                        onClick={fetchRequests}
                        className="p-2 rounded-xl bg-secondary/10 text-secondary hover:bg-secondary/20 transition-all ml-2"
                        title="Refresh"
                    >
                        <Icon name="RefreshCw" size={18} className={isLoading ? "animate-spin" : ""} />
                    </button>
                </div>
            </div>

            {isLoading ? (
                <div className="flex flex-col items-center justify-center py-20 bg-card border border-border rounded-[2rem]">
                    <Icon name="Loader2" size={40} className="animate-spin text-primary/40 mb-4" />
                    <p className="text-muted-foreground font-medium animate-pulse">Loading requests...</p>
                </div>
            ) : filteredRequests.length === 0 ? (
                <div className="text-center py-20 bg-card border border-dashed border-border rounded-[2rem]">
                    <div className="w-16 h-16 bg-muted/30 rounded-full flex items-center justify-center mx-auto mb-4">
                        <Icon name="Inbox" size={30} className="text-muted-foreground/50" />
                    </div>
                    <h3 className="text-lg font-bold text-primary mb-1">No requests found</h3>
                    <p className="text-sm text-muted-foreground">There are no course requests matching your current filter.</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 gap-4">
                    {filteredRequests.map((req) => (
                        <div
                            key={req.id}
                            className="bg-card border border-border rounded-[2rem] p-6 hover:shadow-xl hover:shadow-primary/5 transition-all group"
                        >
                            <div className="flex flex-col md:flex-row gap-6">
                                <div className="flex-1 space-y-4">
                                    <div className="flex items-start justify-between">
                                        <div className="space-y-1">
                                            <div className="flex items-center gap-3">
                                                <h3 className="text-lg font-bold text-primary italic group-hover:text-secondary transition-colors">
                                                    {req.course_title}
                                                </h3>
                                                <span className={cn(
                                                    "px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-tighter border",
                                                    getStatusColor(req.status)
                                                )}>
                                                    {req.status}
                                                </span>
                                            </div>
                                            <div className="flex flex-wrap items-center gap-4 text-xs text-muted-foreground font-medium">
                                                <div className="flex items-center gap-1.5">
                                                    <Icon name="Tag" size={12} className="text-secondary" />
                                                    {req.category || 'No Category'}
                                                </div>
                                                <div className="flex items-center gap-1.5">
                                                    <Icon name="Mail" size={12} className="text-secondary" />
                                                    {req.user_email}
                                                </div>
                                                <div className="flex items-center gap-1.5">
                                                    <Icon name="Calendar" size={12} className="text-secondary" />
                                                    {new Date(req.created_at).toLocaleDateString()}
                                                </div>
                                            </div>
                                        </div>
                                    </div>

                                    {req.description && (
                                        <div className="bg-muted/30 p-4 rounded-2xl border border-border/50">
                                            <p className="text-sm text-foreground/80 leading-relaxed italic">
                                                "{req.description}"
                                            </p>
                                        </div>
                                    )}
                                </div>

                                <div className="flex flex-row md:flex-col gap-2 justify-end">
                                    <h4 className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-1 hidden md:block">Update Status</h4>
                                    <div className="flex md:grid md:grid-cols-2 gap-2">
                                        <button
                                            onClick={() => handleUpdateStatus(req.id, 'reviewed')}
                                            className="px-3 py-2 rounded-xl text-[10px] font-bold bg-blue-500/10 text-blue-600 hover:bg-blue-500 border border-blue-200 hover:text-white transition-all"
                                        >
                                            REVIEW
                                        </button>
                                        <button
                                            onClick={() => handleUpdateStatus(req.id, 'planned')}
                                            className="px-3 py-2 rounded-xl text-[10px] font-bold bg-purple-500/10 text-purple-600 hover:bg-purple-500 border border-purple-200 hover:text-white transition-all"
                                        >
                                            PLAN
                                        </button>
                                        <button
                                            onClick={() => handleUpdateStatus(req.id, 'completed')}
                                            className="px-3 py-2 rounded-xl text-[10px] font-bold bg-green-500/10 text-green-600 hover:bg-green-500 border border-green-200 hover:text-white transition-all"
                                        >
                                            FINISH
                                        </button>
                                        <button
                                            onClick={() => handleDelete(req)}
                                            className="px-3 py-2 rounded-xl text-[10px] font-bold bg-red-500/10 text-red-600 hover:bg-red-500 border border-red-200 hover:text-white transition-all"
                                        >
                                            DELETE
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            <ConfirmationModal
                isOpen={!!requestToDelete}
                onClose={() => setRequestToDelete(null)}
                onConfirm={confirmDelete}
                title="Delete Course Request"
                message={`Are you sure you want to delete the request for "${requestToDelete?.course_title}"? This action cannot be undone.`}
                type="danger"
                confirmText={isDeleting ? "Deleting..." : "Delete Request"}
            />
        </div>
    );
};

export default CourseRequestManagement;
