import React, { useState, useEffect } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';

const RewardManagement = () => {
    const { addToast } = useToast();
    const [waitlistEntries, setWaitlistEntries] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        fetchWaitlist();

        // Subscribe to real-time waitlist joins
        const channel = supabaseService.supabase.channel('admin_notifications');
        
        channel.on('broadcast', { event: 'WAITLIST_JOINED' }, () => {
            console.log("RewardManagement: Waitlist joined event received, refreshing...");
            fetchWaitlist();
        });

        channel.subscribe();

        return () => {
            supabaseService.supabase.removeChannel(channel);
        };
    }, []);

    const fetchWaitlist = async () => {
        setIsLoading(true);
        try {
            const data = await supabaseService.getFoundersWaitlistEntries();
            setWaitlistEntries(data);
        } catch (err) {
            console.error("Failed to fetch waitlist:", err);
            addToast("Failed to load waitlist entries", "error");
        } finally {
            setIsLoading(false);
        }
    };

    const handleUpdateStatus = (id, newStatus) => {
        // Logic for updating status would go here
        addToast(`Fulfillment status updated to ${newStatus}`, "success");
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h2 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight italic uppercase">Founders Gear <span className="text-secondary">Waitlist</span></h2>
                    <p className="text-sm text-slate-500 dark:text-slate-400">Track and manage scholars who have joined the elite gear waitlist.</p>
                </div>
                <div className="flex gap-2">
                    <Button variant="outline" size="sm" iconName="RefreshCw" onClick={fetchWaitlist}>Refresh</Button>
                    <Button variant="default" size="sm" iconName="Download">Export List</Button>
                </div>
            </div>

            <div className="bg-card border border-border rounded-3xl overflow-hidden shadow-sm">
                <div className="overflow-x-auto custom-scrollbar">
                    <table className="w-full text-left border-collapse min-w-[800px]">
                        <thead>
                            <tr className="bg-muted/50 border-b border-border">
                                <th className="px-4 md:px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500">Scholar</th>
                                <th className="px-4 md:px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500">Gear Item</th>
                                <th className="px-4 md:px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500">Status</th>
                                <th className="px-4 md:px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500">Date Joined</th>
                                <th className="px-4 md:px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {isLoading ? (
                                <tr>
                                    <td colSpan="5" className="px-6 py-12 text-center text-slate-400 italic font-medium">Loading waitlist data...</td>
                                </tr>
                            ) : waitlistEntries.length === 0 ? (
                                <tr>
                                    <td colSpan="5" className="px-6 py-12 text-center text-slate-400 italic font-medium">No scholars have joined the waitlist yet.</td>
                                </tr>
                            ) : waitlistEntries.map((entry) => (
                                <tr key={entry.id} className="hover:bg-muted/30 transition-colors">
                                    <td className="px-4 md:px-6 py-6">
                                        <div className="flex items-center gap-3">
                                            {entry.profile?.avatar_url ? (
                                                <img src={entry.profile.avatar_url} alt="" className="w-10 h-10 rounded-full border border-border" />
                                            ) : (
                                                <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold shrink-0">
                                                    {entry.profile?.full_name?.charAt(0) || 'U'}
                                                </div>
                                            )}
                                            <div className="min-w-0">
                                                <p className="text-sm font-bold text-slate-900 dark:text-white truncate max-w-[150px]">{entry.profile?.full_name || 'Unknown Scholar'}</p>
                                                <p className="text-xs text-slate-500 truncate max-w-[150px]">{entry.profile?.email}</p>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-4 md:px-6 py-6">
                                        <div className="flex items-center gap-2">
                                            <Icon name="ShoppingBag" size={16} className="text-secondary" />
                                            <span className="text-xs font-bold text-slate-700 dark:text-slate-300">Elite Founder Backpack</span>
                                        </div>
                                    </td>
                                    <td className="px-4 md:px-6 py-6">
                                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-widest bg-amber-500/10 text-amber-500">
                                            Waitlisted
                                        </span>
                                    </td>
                                    <td className="px-4 md:px-6 py-6">
                                        <p className="text-xs font-medium text-slate-600 dark:text-slate-400">{new Date(entry.joined_at).toLocaleDateString()}</p>
                                    </td>
                                    <td className="px-4 md:px-6 py-6 text-right">
                                        <Button 
                                            variant="ghost" 
                                            size="sm" 
                                            className="text-primary hover:bg-primary/5 font-black uppercase text-[10px] tracking-widest"
                                            onClick={() => handleUpdateStatus(entry.id, 'invited')}
                                        >
                                            Send Invite
                                        </Button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default RewardManagement;
