import React from 'react';
import Icon from '../../../components/AppIcon';

const QuickActionCard = ({ title, description, icon, iconBg, onClick }) => {
  return (
    <button
      onClick={onClick}
      className="bg-card rounded-xl p-6 shadow-[0_4px_12px_rgba(27,54,93,0.08)] transition-all duration-300 hover:shadow-[0_8px_24px_rgba(27,54,93,0.12)] hover:scale-105 text-left w-full"
    >
      <div className={`w-12 h-12 rounded-xl flex items-center justify-center mb-4 ${iconBg}`}>
        <Icon name={icon} size={24} color="#FFFFFF" />
      </div>
      <h3 className="text-base md:text-lg font-semibold text-foreground mb-2">{title}</h3>
      <p className="text-sm text-muted-foreground">{description}</p>
    </button>
  );
};

export default QuickActionCard;