import React, { useState, useEffect } from 'react';
import { supabase } from '../../../utils/supabaseClient';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';

const PeerRatingsManagement = () => {
    const [ratings, setRatings] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    const fetchRatings = async () => {
        setIsLoading(true);
        try {
            // In a real app we would join with user profiles, but for now we'll just show raw
            const { data, error } = await supabase
                .from('peer_sync_ratings')
                .select('*')
                .order('created_at', { ascending: false })
                .limit(50);
                
            if (error) {
                // If table doesn't exist yet, we catch it
                console.warn("Table might not exist yet", error);
                setRatings([]);
            } else {
                setRatings(data || []);
            }
        } catch (e) {
            console.error(e);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchRatings();
    }, []);

    return (
        <div className="bg-card rounded-2xl shadow-xl border border-border p-6">
            <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-emerald-500/10 rounded-xl">
                        <Icon name="Star" className="text-emerald-500" size={24} />
                    </div>
                    <div>
                        <h2 className="text-2xl font-black text-foreground">Peer Sync Ratings</h2>
                        <p className="text-sm text-muted-foreground">Monitor collaborative session feedback.</p>
                    </div>
                </div>
                <Button 
                    variant="outline" 
                    iconName="RefreshCw" 
                    onClick={fetchRatings} 
                    className={isLoading ? "animate-spin" : ""}
                />
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left text-sm text-muted-foreground">
                    <thead className="bg-muted/50 text-foreground font-bold text-xs uppercase tracking-wider">
                        <tr>
                            <th className="px-4 py-3 rounded-l-lg">Date</th>
                            <th className="px-4 py-3">Rater ID</th>
                            <th className="px-4 py-3">Room / Session</th>
                            <th className="px-4 py-3 rounded-r-lg">Score</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border/50">
                        {ratings.length === 0 ? (
                            <tr>
                                <td colSpan="4" className="px-4 py-8 text-center">
                                    {isLoading ? "Loading ratings..." : "No ratings submitted yet."}
                                </td>
                            </tr>
                        ) : (
                            ratings.map((r, i) => (
                                <tr key={i} className="hover:bg-muted/30 transition-colors">
                                    <td className="px-4 py-3">{new Date(r.created_at).toLocaleString()}</td>
                                    <td className="px-4 py-3 font-mono text-xs">{r.rater_id}</td>
                                    <td className="px-4 py-3 font-mono text-xs">{r.room_id}</td>
                                    <td className="px-4 py-3">
                                        {r.rating === 'good' ? (
                                            <span className="inline-flex items-center gap-1 text-emerald-500 font-bold bg-emerald-500/10 px-2 py-1 rounded">
                                                <Icon name="ThumbsUp" size={14} /> Great
                                            </span>
                                        ) : r.rating === 'bad' ? (
                                            <span className="inline-flex items-center gap-1 text-red-500 font-bold bg-red-500/10 px-2 py-1 rounded">
                                                <Icon name="ThumbsDown" size={14} /> Poor
                                            </span>
                                        ) : (
                                            <span className="inline-flex items-center gap-1 text-slate-500 font-bold bg-slate-500/10 px-2 py-1 rounded">
                                                <Icon name="MinusCircle" size={14} /> Skipped
                                            </span>
                                        )}
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default PeerRatingsManagement;
